import {
    LayoutPanelLeft,
    Pencil
} from 'lucide-react';

import { DynamicForm } from '@/Components/Core/DynamicCrud/DynamicForm';
import StatusBadge from '@/Components/UI/StatusBadge';
import { usePermission } from '@/Hooks/usePermission';
import { useTranslations } from '@/Hooks/useTranslations';
import type { CrudConfig, CrudPageProps } from '@/Types/crud';

export function useLoanRequest(props: CrudPageProps): CrudConfig {

    const { t } = useTranslations();

    const modelProperty = props?.modelProperty;
    const advanceFilterOptions = props?.advanceFilterOptions || [];
    const routePrefix = modelProperty?.routePrefix;

    const { can } = usePermission();


    const baseBreadcrumbs = [
        { label: t('Dashboard'), href: route('backend.dashboard') },
        { label: t('Loan Reqquest'), href: route(`${routePrefix}.index`) },
    ];

    return {

        formComponent: DynamicForm,
        fetchToggle: false,
        form: {
            title: {
                create: t('Create Loan Lequest'),
                edit: t('Edit Loan Lequest'),
            },
            description: {
                create: t('Add a new loan Lequest to the system'),
                edit: t('Update loan Lequest information'),
            },
            submitButtonText: {
                create: t('Create Loan Lequest'),
                edit: t('Update Loan Lequest'),
            },

            fields: [

            ],
        },

        formValidationRules: {


        },

        resource: 'LoanRequest',
        resourcePlural: 'LoanRequests',
        title: t('Loan Requests'),
        description: t('Manage Loan Requests Management'),

        routes: {
            index: `${routePrefix}.index`,
            destroy: `${routePrefix}.destroy`,
        },

        formDisplayMode: 'modal',
        viewDisplayMode: 'modal',
        statusType: 'binary',

        breadcrumbs: {
            index: [
                { label: t('Dashboard'), href: route('backend.dashboard') },
                { label: t('Loan Requests'), href: null, active: true },
            ],
            create: [
                ...baseBreadcrumbs,
                { label: t('Create'), href: null, active: true },
            ],
            update: [
                ...baseBreadcrumbs,
                { label: t('Update'), href: null, active: true },
            ],
        },

        table: {
            selectable: false,
            searchable: true,
            serializable: true,
            searchPlaceholder: t('Search FAQs by question, answer...'),
            sortable: true,
            defaultSort: 'created_at',
            defaultSortDirection: 'desc',
            emptyMessage: t('No Loan Requests available. Create your first Loan Product to get started.'),
            emptyMessageIcon: LayoutPanelLeft,



            columns: [
                {
                    key: 'order_id',
                    label: t('Order Id'),
                    sortable: false,
                    filterable: true,
                    priority: 0,

                },

                {
                    key: 'user_info',
                    label: 'User',
                    render: (row: any) => (

                        row.user ? (

                            <div className="flex flex-col gap-0.5 text-xs">
                                <span><span className="text-gray-400">{t('Name')}:</span> {row.user?.name ?? '--'}</span>
                                <span><span className="text-gray-400">{t('Email')}:</span> {row.user?.email ?? '--'}</span>
                            </div>

                        ) : "--"


                    )
                },

                {
                    key: 'loan_info',
                    label: 'Loan Information',
                    render: (row: any) => (
                        < div className="flex flex-col gap-0.5 text-xs" >
                            <span><span className="text-gray-400">{t('Amount')}:</span> {row.amount}</span>
                            <span><span className="text-gray-400">{t('Product')}:</span> {row?.loanProduct?.name || '--'}</span>
                            <span className="text-gray-400 mt-0.5">{t('Interest Rate')}:</span> {row?.loanProduct?.daily_interest_rate || 0} %
                        </div >
                    )
                },

                {
                    key: 'repayment_info',
                    label: 'Repayment Information',
                    render: (row: any) => (
                        <div className="flex flex-col gap-0.5 text-xs">
                            <span><span className="text-gray-400">{t('Repayment Period')}:</span> {row.loanProduct?.repayment_period} Days</span>
                            <span><span className="text-gray-400">{t('Repayment Method')}:</span> {row.loanProduct?.repayment_method}</span>
                        </div>
                    )
                },



                {
                    key: 'status',
                    label: 'Status',
                    sortable: false,
                    filterable: false,
                    priority: 3,
                    render: (row: any) => {

                        const openStatusModal = () => {
                            window.dispatchEvent(
                                new CustomEvent('open-status-modal', {
                                    detail: {
                                        id: row.id,
                                        status: row.status,
                                        note: row.note
                                    }
                                })
                            );
                        };

                        return (
                            <div className="flex items-center gap-2">

                                <StatusBadge status={row.status} />

                                {can('loan-request.edit') && (
                                    <button
                                        onClick={openStatusModal}
                                        className="p-1 rounded hover:bg-gray-200 dark:hover:bg-gray-700 transition"
                                        title="Update Status"
                                    >
                                        <Pencil className="w-4 h-4 text-gray-600" />
                                    </button>
                                )}
                            </div>
                        );
                    },
                },

                {
                    key: 'created_at',
                    label: t('Created at'),
                    sortable: false,
                    priority: 4,
                    renderType: 'date',
                },
            ],

        },


        filters: {
            searchFields: ['order_id', 'username', 'email', 'phone'],
            filterFields: advanceFilterOptions,
        },

        permissions: {
            actions: {
                create: 'loan-request.create',
                edit: 'loan-request.edit',
                view: 'loan-request.view',
                delete: 'loan-request.delete',
            },
        },

        actionConstraints: {
            delete: [
                {
                    field: 'is_owner',
                    checkValue: true,
                    message: 'Cannot delete owner account',
                },
                {
                    field: 'orders_count',
                    message: 'Cannot delete FAQ with existing orders',
                },
            ],
            bulkDelete: [
                {
                    field: 'is_owner',
                    checkValue: true,
                    message: 'Cannot delete owner account',
                },
            ],
        },

        destroyDialogConfig: {

            title: t(`Delete Loan request`),
            description: t(`Are you sure you want to delete this Loan request? This action cannot be undone.`),

        },

        labels: {
            singular: 'Loan request',
            plural: 'Loan requests',
            key: 'loan_request',
        },

        saveAlertInfo: {
            title: t('Loan Account Configuration'),
            description: t('Fill in the details below to save the FAQ account. All fields marked as required must be completed.'),
        }
    }
};

